    // verify that all matchers listed in all licenses exist in the matcher list
    List<Node> nodes = XmlUtils.getNodes(doc, xPath, "/rat-config/licenses/license/*");
    nodes.stream().filter(n -> n.getNodeType() == Node.ELEMENT_NODE && !"note".equals(n.getNodeName())).forEach(n -> assertNotNull(MatcherBuilderTracker.getMatcherBuilder(n.getNodeName()), () -> String.format("Missing matcher named '%s'", n.getNodeName())));
