        assertThat(osi.closeCount).isEqualTo(0);
        try (OutputStream os = config.getOutput().get()) {
            assertThat(os).isNotNull();
            assertThat(osi.closeCount).isEqualTo(0);
        }
        assertThat(osi.closeCount).isEqualTo(1);
